const trendsResult = $('Postgres: Get Top Trends').all().map(i => i.json);
const historyResult = $('Postgres: Get Idea History').all().map(i => i.json.topic_title);
const count = Number($('Webhook: /generate-ideas').item.json.body.count || 5);
const projectId = $('Webhook: /generate-ideas').item.json.body.project_id;

const trendsList = trendsResult.map(t => `- ${t.topic} (${t.percentage}% of competitor posts)`).join('\n') || 'No trend data yet — generate general small-business content ideas.';
const historyList = historyResult.length ? historyResult.join('; ') : 'none yet';

const prompt = `You are a local marketing assistant. Based on these competitor content trends:\n${trendsList}\n\nGenerate ${count} NEW Google Maps post ideas for our client business. DO NOT repeat or closely rephrase any of these previously generated titles: ${historyList}.\n\nIMPORTANT — stay factually grounded: do NOT invent specific facts that are not present in the trend data above. Do not name fictional employees, do not invent specific event dates, prices, statistics, or quotes from real people. Keep post_copy general and marketing-oriented — describe the TYPE of offer, service, or seasonal theme (e.g. \"a cozy seasonal drink special\") rather than fabricating a specific occurrence (e.g. do NOT write \"Join Sarah for our pumpkin spice launch on Oct 3rd\" — no real business detail was given to support that).\n\nReturn ONLY a valid JSON array (no markdown, no preamble) where each item has exactly this shape:\n{"topic_title": string, "post_copy": string (160-300 characters), "keywords": string[], "cta_type": one of [call, visit, book, buy, learn], "cta_text": string, "image_concept": string}`;

return { json: { prompt, project_id: projectId, count } };

const raw = $input.item.json;
let text = raw.candidates[0].content.parts[0].text;
text = text.replace(/```json|```/g, '').trim();
let ideas;
try {
  ideas = JSON.parse(text);
  if (!Array.isArray(ideas)) ideas = [ideas];
} catch (e) {
  ideas = [];
}
return ideas.map(idea => ({ json: idea }));
